def gcd(a,b):
    while b: a,b=b,a%b
    return a

def max_of(l):
    m=l[0]
    for x in l[1:]:
        if x>m: m=x
    return m

def flatten(l):
    o=[]
    for s in l:
        for x in s: o.append(x)
    return o

def char_count(s):
    d={}
    for c in s: d[c]=d.get(c,0)+1
    return d

def remove_dupes(l):
    o=[]
    for x in l:
        if x not in o: o.append(x)
    return o
